{
  "a_sentences": [
    {
      "a_text": "Die Versicherte bestreitet, dass die Vorinstanz die rentenablehnende Verfügung vom 4. Juli 2024 zu Recht bestätigte, und rügt die Beurteilung der Arbeitsfähigkeit sowie die erwerblichen Auswirkungen der Gesundheitsschädigung (P1, P2).",
      "b_propositions": ["P1", "P2"]
    },
    {
      "a_text": "Das Bundesgericht wendet die Bestimmungen und Grundsätze zur Invalidität (Art. 8 ATSG), zum Anspruch auf eine Invalidenrente (Art. 28 IVG) sowie zur Anspruchsprüfung bei einer Neuanmeldung nach vorausgegangener Ablehnung des Rentenanspruchs unter analoger Anwendung der Grundsätze zur Rentenrevision nach Art. 17 ATSG an (P3).",
      "b_propositions": ["P3"]
    },
    {
      "a_text": "Die Invaliditätsbemessung bei erwerbstätigen Versicherten richtet sich nach Art. 16 ATSG (Art. 28a IVG), indem das Invalideneinkommen dem Valideneinkommen gegenübergestellt wird (P4).",
      "b_propositions": ["P4"]
    },
    {
      "a_text": "Der Beweiswert ärztlicher Berichte hängt davon ab, ob sie für die streitigen Belange umfassend sind, auf allseitigen Untersuchungen beruhen, die geklagten Beschwerden berücksichtigen, in Kenntnis der Vorakten abgegeben wurden, in der Beurteilung einleuchten und begründete Schlussfolgerungen enthalten (P5).",
      "b_propositions": ["P5"]
    },
    {
      "a_text": "Das Bundesgericht erachtet es als nicht zu beanstanden, dass die Vorinstanz auf die RAD-Stellungnahmen abstellte und auf weitere medizinische Abklärungen verzichtete (P6).",
      "b_propositions": ["P6"]
    },
    {
      "a_text": "Auch die Einwände der Versicherten zu den erwerblichen Auswirkungen der Gesundheitsschädigung begründen keine Bundesrechtsverletzung (P7).",
      "b_propositions": ["P7"]
    },
    {
      "a_text": "Damit bleibt es bei der vorinstanzlichen Ermittlung eines rentenausschliessenden Invaliditätsgrades (P8).",
      "b_propositions": ["P8"]
    }
  ]
}
